      try {
        var w = ifr && ifr.contentWindow;
        if (w && typeof w.hpScanFromShell === 'function') {
          while (vPend.length) { try { w.hpScanFromShell(vPend.shift()); } catch (e) { break; } }
        }
      } catch (e) {}
